1	package skilldiscovery
2	
3	import (
4		"context"
5		"errors"
6		"log/slog"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11	
12		"golang.org/x/mod/semver"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16	)
17	
18	// InvocationForm builds an agent's invocation string for a discovered skill.
19	// The only thing that differs between agents is the prefix and namespace
20	// joiner: Claude Code uses slash form (`/name`, `/plugin:name`), codex uses
21	// dollar form (`$name`, `$plugin:name`) — the literal token a user types to
22	// invoke the skill in that CLI. Discovery emits Name already in this form so
23	// downstream prompt composition stays agent-agnostic and joins verbatim.
24	type InvocationForm func(name, pluginName string) string
25	
26	// SlashForm is Claude Code's invocation syntax: "/name" or "/plugin:name".
27	func SlashForm(name, pluginName string) string {
28		if pluginName == "" {
29			return "/" + name
30		}
31		return "/" + pluginName + ":" + name
32	}
33	
34	// DollarForm is codex's invocation syntax: "$name" or "$plugin:name". This is
35	// the explicit "use this skill" token from codex's own injected skills
36	// catalog ("name a skill with $SkillName or plain text").
37	func DollarForm(name, pluginName string) string {
38		if pluginName == "" {
39			return "$" + name
40		}
41		return "$" + pluginName + ":" + name
42	}
43	
44	// DedupeByInvocation collapses entries sharing an invocation name, keeping the
45	// first occurrence. Plugins can ship a skill and a same-named wrapper that
46	// forwards to it; scan order decides which wins.
47	func DedupeByInvocation(in []agent.DiscoveredSkill) []agent.DiscoveredSkill {
48		if len(in) < 2 {
49			return in
50		}
51		seen := make(map[string]struct{}, len(in))
52		out := make([]agent.DiscoveredSkill, 0, len(in))
53		for _, s := range in {
54			if _, dup := seen[s.Name]; dup {
55				continue
56			}
57			seen[s.Name] = struct{}{}
58			out = append(out, s)
59		}
60		return out
61	}
62	
63	// ScanPluginCache walks <root>/<marketplace>/<plugin>/<version>/ and invokes
64	// scanVersion once per plugin, for the single version directory chosen by
65	// PickLatestVersion. The callback receives the chosen version root and the
66	// plugin name (used as the invocation namespace). Both Claude Code and codex
67	// use this same market/plugin/version cache layout; they differ only in which
68	// subdirectories under the version root they scan and their invocation form.
69	func ScanPluginCache(ctx context.Context, root string, scanVersion func(versionRoot, pluginName string) []agent.DiscoveredSkill) []agent.DiscoveredSkill {
70		entries, err := os.ReadDir(root)
71		if err != nil {
72			logging.Debug(ctx, "skill discovery: plugin cache unreadable",
73				slog.String("root", root), slog.String("error", err.Error()))
74			return nil
75		}
76		var found []agent.DiscoveredSkill
77		for _, marketEntry := range entries {
78			if !marketEntry.IsDir() {
79				continue
80			}
81			marketRoot := filepath.Join(root, marketEntry.Name())
82			pluginEntries, err := os.ReadDir(marketRoot)
83			if err != nil {
84				continue
85			}
86			for _, pluginEntry := range pluginEntries {
87				if !pluginEntry.IsDir() {
88					continue
89				}
90				pluginName := pluginEntry.Name()
91				pluginRoot := filepath.Join(marketRoot, pluginName)
92				versionEntries, err := os.ReadDir(pluginRoot)
93				if err != nil {
94					continue
95				}
96				versionDir, ok := PickLatestVersion(versionEntries)
97				if !ok {
98					continue
99				}
100				found = append(found, scanVersion(filepath.Join(pluginRoot, versionDir), pluginName)...)
101			}
102		}
103		return found
104	}
105	
106	// PickLatestVersion returns the "newest" version directory name among entries:
107	//
108	//   - If any entry parses as semver (with or without a leading "v"), pick the
109	//     highest semver; non-semver entries are ignored when a semver exists.
110	//   - Otherwise fall back to the lexicographic max of all directory names.
111	//     This handles the "unknown" sentinel some plugins ship, and the opaque
112	//     content-hash version dirs codex plugins use (e.g. "fef63ecf").
113	//
114	// Returns ("", false) if no usable directory entry exists.
115	func PickLatestVersion(entries []os.DirEntry) (string, bool) {
116		var dirs []string
117		for _, e := range entries {
118			if e.IsDir() {
119				dirs = append(dirs, e.Name())
120			}
121		}
122		if len(dirs) == 0 {
123			return "", false
124		}
125		var semverDirs []string
126		for _, d := range dirs {
127			if semver.IsValid(semverWithV(d)) {
128				semverDirs = append(semverDirs, d)
129			}
130		}
131		if len(semverDirs) > 0 {
132			sort.Slice(semverDirs, func(i, j int) bool {
133				return semver.Compare(semverWithV(semverDirs[i]), semverWithV(semverDirs[j])) > 0
134			})
135			return semverDirs[0], true
136		}
137		sort.Sort(sort.Reverse(sort.StringSlice(dirs)))
138		return dirs[0], true
139	}
140	
141	// semverWithV ensures a version string has the "v" prefix golang.org/x/mod/semver
142	// requires. Plugin version dirs are usually bare (e.g. "0.1.0").
143	func semverWithV(s string) string {
144		if strings.HasPrefix(s, "v") {
145			return s
146		}
147		return "v" + s
148	}
149	
150	// ScanSkillsDir reads each <dir>/<name>/SKILL.md, parses its frontmatter, and
151	// emits a DiscoveredSkill (in invoke's form) when Matches() returns true.
152	// pluginName is the namespace ("" for un-namespaced user skills). Missing dirs
153	// yield nil — discovery is best-effort.
154	func ScanSkillsDir(ctx context.Context, dir, pluginName string, invoke InvocationForm) []agent.DiscoveredSkill {
155		entries, err := os.ReadDir(dir)
156		if err != nil {
157			return nil
158		}
159		var found []agent.DiscoveredSkill
160		for _, skillEntry := range entries {
161			if !skillEntry.IsDir() {
162				continue
163			}
164			skillFile := filepath.Join(dir, skillEntry.Name(), "SKILL.md")
165			data, err := os.ReadFile(skillFile) //nolint:gosec // G304: skillFile is built from a ReadDir walk under HOME, not user input
166			if err != nil {
167				continue
168			}
169			name, description, parseErr := ParseSkillFrontmatter(data)
170			if parseErr != nil {
171				logging.Debug(ctx, "skill discovery: skipping malformed SKILL.md",
172					slog.String("path", skillFile), slog.String("error", parseErr.Error()))
173				continue
174			}
175			if name == "" {
176				name = skillEntry.Name()
177			}
178			invocation := invoke(name, pluginName)
179			if !Matches(invocation, description) {
180				continue
181			}
182			found = append(found, agent.DiscoveredSkill{
183				Name:        invocation,
184				Description: description,
185				SourcePath:  skillFile,
186			})
187		}
188		return found
189	}
190	
191	// ScanFlatMarkdownDir reads *.md files directly under dir (no nesting), parses
192	// their frontmatter for `description:`, and derives the invocation name from
193	// the filename (minus .md). Used by Claude Code for plugin/user commands and
194	// agents, whose frontmatter has no `name:` field. README.md is skipped.
195	func ScanFlatMarkdownDir(ctx context.Context, dir, pluginName string, invoke InvocationForm) []agent.DiscoveredSkill {
196		entries, err := os.ReadDir(dir)
197		if err != nil {
198			return nil
199		}
200		var found []agent.DiscoveredSkill
201		for _, entry := range entries {
202			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".md") {
203				continue
204			}
205			baseName := strings.TrimSuffix(entry.Name(), ".md")
206			if strings.EqualFold(baseName, "README") {
207				continue
208			}
209			filePath := filepath.Join(dir, entry.Name())
210			data, err := os.ReadFile(filePath) //nolint:gosec // G304: filePath is built from a ReadDir walk under HOME, not user input
211			if err != nil {
212				continue
213			}
214			_, description, parseErr := ParseSkillFrontmatter(data)
215			if parseErr != nil {
216				logging.Debug(ctx, "skill discovery: skipping malformed command/agent",
217					slog.String("path", filePath), slog.String("error", parseErr.Error()))
218				continue
219			}
220			invocation := invoke(baseName, pluginName)
221			if !Matches(invocation, description) {
222				continue
223			}
224			found = append(found, agent.DiscoveredSkill{
225				Name:        invocation,
226				Description: description,
227				SourcePath:  filePath,
228			})
229		}
230		return found
231	}
232	
233	// ParseSkillFrontmatter extracts `name:` and `description:` from a minimal YAML
234	// frontmatter block — the tiny subset these SKILL.md / command / agent files
235	// use. Surrounding double-quotes are trimmed so `description: "foo"` returns
236	// `foo`.
237	func ParseSkillFrontmatter(data []byte) (name, description string, err error) {
238		s := string(data)
239		if !strings.HasPrefix(s, "---\n") && !strings.HasPrefix(s, "---\r\n") {
240			return "", "", errors.New("no frontmatter delimiter")
241		}
242		body := strings.TrimPrefix(strings.TrimPrefix(s, "---\r\n"), "---\n")
243		end := strings.Index(body, "\n---")
244		if end < 0 {
245			return "", "", errors.New("no closing frontmatter delimiter")
246		}
247		for _, line := range strings.Split(body[:end], "\n") {
248			line = strings.TrimSpace(line)
249			switch {
250			case strings.HasPrefix(line, "name:"):
251				name = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "name:")), `"`)
252			case strings.HasPrefix(line, "description:"):
253				description = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "description:")), `"`)
254			}
255		}
256		return name, description, nil
257	}
